// Vehicle hierarchy with different space requirements
abstract class Vehicle {
    protected String licensePlate;
    protected VehicleType type;

    public abstract int getRequiredSpotSize();
}

class Car extends Vehicle {
    public int getRequiredSpotSize() { return 1; }
}

class Motorcycle extends Vehicle {
    public int getRequiredSpotSize() { return 1; }
}

class Truck extends Vehicle {
    public int getRequiredSpotSize() { return 2; }  // needs 2 spots
}

record ParkingSpot(int id, SpotType type, boolean isOccupied, Vehicle vehicle) {
    public boolean canFit(Vehicle v) {
        return !isOccupied && type.canAccommodate(v.type);
    }
}

record ParkingTicket(String ticketId, Vehicle vehicle, ParkingSpot spot, 
                     LocalDateTime entryTime, LocalDateTime exitTime) {}

class ParkingFloor {
    private List<ParkingSpot> spots;

    public Optional<ParkingSpot> findAvailableSpot(Vehicle vehicle) {
        return spots.stream()
            .filter(spot -> spot.canFit(vehicle))  // key: match vehicle to spot type
            .findFirst();
    }
}

class ParkingLot {
    private static ParkingLot instance;  // Singleton pattern
    private List<ParkingFloor> floors;
    private FeeCalculator feeCalculator;  // Strategy pattern for pricing

    public synchronized ParkingTicket parkVehicle(Vehicle vehicle) {
        for (var floor : floors) {
            var spot = floor.findAvailableSpot(vehicle);
            if (spot.isPresent()) {
                return new ParkingTicket(UUID.randomUUID().toString(), 
                    vehicle, spot.get(), LocalDateTime.now(), null);
            }
        }
        throw new NoSpotAvailableException();
    }
}

