// Strategy interface defines the contract
interface FeeCalculator {
    BigDecimal calculateFee(ParkingTicket ticket);
}

// Concrete strategy 1: Hourly pricing
class HourlyFeeCalculator implements FeeCalculator {
    private static final BigDecimal HOURLY_RATE = new BigDecimal("5.00");

    public BigDecimal calculateFee(ParkingTicket ticket) {
        long hours = Duration.between(ticket.entryTime(), ticket.exitTime()).toHours();
        return HOURLY_RATE.multiply(BigDecimal.valueOf(Math.max(1, hours)));
    }
}

// Concrete strategy 2: Flat rate regardless of time
class FlatRateFeeCalculator implements FeeCalculator {
    private final BigDecimal flatRate;

    public FlatRateFeeCalculator(BigDecimal rate) { this.flatRate = rate; }

    public BigDecimal calculateFee(ParkingTicket ticket) {
        return flatRate;  // same fee for everyone
    }
}

// Concrete strategy 3: Vehicle type-based pricing
class VehicleTypeFeeCalculator implements FeeCalculator {
    private final Map<VehicleType, BigDecimal> ratesByType;

    public VehicleTypeFeeCalculator() {
        this.ratesByType = Map.of(
            VehicleType.MOTORCYCLE, new BigDecimal("2.00"),
            VehicleType.CAR, new BigDecimal("5.00"),
            VehicleType.TRUCK, new BigDecimal("10.00")
        );
    }

    public BigDecimal calculateFee(ParkingTicket ticket) {
        long hours = Duration.between(ticket.entryTime(), ticket.exitTime()).toHours();
        var baseRate = ratesByType.get(ticket.vehicle().type);
        return baseRate.multiply(BigDecimal.valueOf(Math.max(1, hours)));
    }
}

class ParkingLot {
    private FeeCalculator feeCalculator;  // Strategy injected here

    public void setFeeCalculator(FeeCalculator calculator) {
        this.feeCalculator = calculator;  // swap strategies at runtime
    }

    public BigDecimal calculateParkingFee(ParkingTicket ticket) {
        return feeCalculator.calculateFee(ticket);  // delegate to strategy
    }
}

// Geographic location for each lot
record Location(double latitude, double longitude) {
    public double distanceTo(Location other) {
        // Haversine formula for distance calculation
        return Math.sqrt(Math.pow(latitude - other.latitude, 2) + 
                        Math.pow(longitude - other.longitude, 2)) * 111.0;  // rough km
    }
}

// Each lot now has a location and remains independent
class ParkingLot {
    private final String lotId;
    private final Location location;
    private final List<ParkingFloor> floors;

    public int getAvailableSpotCount() {
        return floors.stream()
            .mapToInt(ParkingFloor::getAvailableSpotCount)
            .sum();
    }

    public boolean hasAvailableSpots() {
        return getAvailableSpotCount() > 0;
    }
}

// Network layer coordinates multiple lots
class ParkingLotNetwork {
    private final Map<String, ParkingLot> parkingLots;  // lotId -> ParkingLot

    public void addParkingLot(ParkingLot lot) {
        parkingLots.put(lot.getLotId(), lot);
    }

    public Optional<ParkingLot> findNearestAvailableLot(Location userLocation) {
        return parkingLots.values().stream()
            .filter(ParkingLot::hasAvailableSpots)  // only lots with capacity
            .min(Comparator.comparingDouble(
                lot -> lot.getLocation().distanceTo(userLocation)));
    }

    public int getTotalOccupancy() {
        return parkingLots.values().stream()
            .mapToInt(ParkingLot::getOccupiedSpotCount)
            .sum();
    }

    public Map<String, Integer> getOccupancyByLocation() {
        return parkingLots.entrySet().stream()
            .collect(Collectors.toMap(
                Map.Entry::getKey,
                entry -> entry.getValue().getOccupiedSpotCount()));
    }
}

