network.addParkingLot(new ParkingLot("LOT-DOWNTOWN", new Location(40.7, -74.0), floors1));
network.addParkingLot(new ParkingLot("LOT-AIRPORT", new Location(40.6, -73.8), floors2));

var userLocation = new Location(40.75, -73.95);
var nearestLot = network.findNearestAvailableLot(userLocation);

// Singleton: one ParkingLot instance system-wide
class ParkingLot {
    private static volatile ParkingLot instance;
    private ParkingLot() {}  // private constructor prevents external instantiation

    public static ParkingLot getInstance() {
        if (instance == null) {
            synchronized (ParkingLot.class) {
                if (instance == null) instance = new ParkingLot();  // double-checked locking
            }
        }
        return instance;
    }
}

