// Observer: display boards react to spot changes
interface ParkingObserver {
    void update(ParkingSpot spot);
}

class DisplayBoard implements ParkingObserver {
    public void update(ParkingSpot spot) {
        System.out.println("Spot " + spot.id() + " now: " + 
            (spot.isOccupied() ? "OCCUPIED" : "AVAILABLE"));
    }
}

class ParkingSpot {
    private List<ParkingObserver> observers = new ArrayList<>();

    public void attach(ParkingObserver observer) { observers.add(observer); }

    public void occupy(Vehicle vehicle) {
        this.vehicle = vehicle;
        this.isOccupied = true;
        notifyObservers();  // automatic notification
    }

    private void notifyObservers() {
        observers.forEach(obs -> obs.update(this));
    }
}

// Factory Method: centralized vehicle creation
class VehicleFactory {
    public static Vehicle createVehicle(String type, String plate) {
        return switch (type.toUpperCase()) {
            case "CAR" -> new Car(plate);
            case "MOTORCYCLE" -> new Motorcycle(plate);
            case "TRUCK" -> new Truck(plate);
            default -> throw new IllegalArgumentException("Unknown vehicle type: " + type);
        };
    }
}

// Builder: readable construction of complex tickets
class ParkingTicket {
    public static class Builder {
        private String ticketId;
        private Vehicle vehicle;
        private ParkingSpot spot;

        public Builder ticketId(String id) { this.ticketId = id; return this; }
        public Builder vehicle(Vehicle v) { this.vehicle = v; return this; }
        public Builder spot(ParkingSpot s) { this.spot = s; return this; }

        public ParkingTicket build() {
            return new ParkingTicket(ticketId, vehicle, spot, LocalDateTime.now());
        }
    }
}

