// Approach 1: Synchronized method (coarse-grained)
class ParkingLot {
    private List<ParkingFloor> floors;

    public synchronized ParkingTicket parkVehicle(Vehicle vehicle) {
        for (var floor : floors) {
            var spot = floor.findAvailableSpot(vehicle);
            if (spot.isPresent()) {
                var actualSpot = spot.get();
                actualSpot.occupy(vehicle);  // mark as occupied
                return new ParkingTicket(UUID.randomUUID().toString(), 
                    vehicle, actualSpot, LocalDateTime.now());
            }
        }
        throw new NoSpotAvailableException();
    }
}

// Approach 2: Fine-grained locking per spot
class ParkingSpot {
    private final ReentrantLock lock = new ReentrantLock();
    private volatile boolean isOccupied;  // volatile ensures visibility across threads
    private Vehicle vehicle;

    public boolean tryOccupy(Vehicle v) {
        if (lock.tryLock()) {  // non-blocking attempt
            try {
                if (!isOccupied) {  // double-check inside lock
                    this.vehicle = v;
                    this.isOccupied = true;
                    return true;
                }
                return false;
            } finally {
                lock.unlock();
            }
        }
        return false;  // couldn't acquire lock
    }
}

class ParkingFloor {
    private final ConcurrentHashMap<Integer, ParkingSpot> spots;  // thread-safe map

    public Optional<ParkingSpot> findAndOccupySpot(Vehicle vehicle) {
        for (var spot : spots.values()) {
            if (spot.canFit(vehicle) && spot.tryOccupy(vehicle)) {
                return Optional.of(spot);  // successfully occupied
            }
        }
        return Optional.empty();
    }
}

// Approach 3: Atomic operations for lock-free updates
class ParkingSpot {
    private final AtomicBoolean isOccupied = new AtomicBoolean(false);
    private volatile Vehicle vehicle;

    public boolean tryOccupy(Vehicle v) {
        if (isOccupied.compareAndSet(false, true)) {  // atomic compare-and-swap
            this.vehicle = v;
            return true;
        }
        return false;  // already occupied
    }
}
